const d = new Date(Date.now() - 24 * 60 * 60 * 1000);
const pad = n => String(n).padStart(2, '0');
const ymd = `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
return [{ json: { dateLabel: ymd } }];

const rawResp = $input.first().json;
const entries = Array.isArray(rawResp) ? rawResp : (rawResp.data || rawResp.log || []);

// RouterOS tags severity directly in "topics" (e.g. "system,error"), so that's the primary signal.
// A supplementary keyword check catches info-level entries that still matter.
const severityMatch = /error|warning|critical/i;
const keywordMatch = /reboot|password|login failure|failed login|blocked|dropped|reject|dos attack|flood|link down|link up|disconnect|timeout|expired|certificate|license|out of memory|high cpu/i;

const filtered = entries.filter(e => {
  const topics = (e.topics || '').toLowerCase();
  const msg = e.message || '';
  return severityMatch.test(topics) || keywordMatch.test(msg);
});

const counts = new Map();
for (const e of filtered) {
  const key = `[${e.topics || 'unknown'}] ${e.message || ''}`.trim();
  counts.set(key, (counts.get(key) || 0) + 1);
}
const deduped = [...counts.entries()].map(([msg, n]) => n > 1 ? `[x${n}] ${msg}` : msg);

return [{
  json: {
    text: deduped.join('\n'),
    originalCount: entries.length,
    filteredCount: filtered.length,
    dedupedCount: deduped.length,
    dateLabel: $('Compute Date Range').first().json.dateLabel
  }
}];

const data = $input.first().json;
const lines = data.text.split('\n').filter(Boolean);
const CHUNK_SIZE = 1200;
const chunks = [];
for (let i = 0; i < lines.length; i += CHUNK_SIZE) {
  chunks.push(lines.slice(i, i + CHUNK_SIZE).join('\n'));
}
if (chunks.length === 0) chunks.push('(no notable lines after filtering)');

return chunks.map((text, idx) => ({
  json: {
    text,
    chunkIndex: idx + 1,
    totalChunks: chunks.length,
    dateLabel: data.dateLabel
  }
}));

const content = $input.item.json.text ?? '';
const chunkInfo = $('Chunk Log For Analysis').item.json;
return [{ json: { chunkIndex: chunkInfo.chunkIndex, extracted: content } }];

const items = $input.first().json.data || [];
const list = items.map(i => i.extracted).filter(Boolean);
const meaningful = list.filter(x => x.trim().toUpperCase() !== 'NONE');
const combined = meaningful.length ? meaningful.join('\n') : 'NONE';

return [{
  json: {
    combinedIssues: combined,
    totalChunks: list.length,
    dateLabel: $('Compute Date Range').first().json.dateLabel
  }
}];

const item = $input.first().json;

const cpuLoad = item['cpu-load'] ?? 'unknown';
const freeMem = parseInt(item['free-memory'] ?? 0, 10);
const totalMem = parseInt(item['total-memory'] ?? 0, 10);
const memUsedPct = totalMem ? (((totalMem - freeMem) / totalMem) * 100).toFixed(1) : 'unknown';
const uptime = item.uptime ?? 'unknown';
const boardName = item['board-name'] ?? 'unknown';

const health = item.health || [];
const healthLines = health.map(h => `${h.name}: ${h.value}${h.type || ''}`);

const interfaces = item.interfaces || [];
const ifaceSummaries = interfaces
  .filter(i => !/loopback/i.test(i.type || ''))
  .map(i => {
    const running = (i.running === true || i.running === 'true');
    const disabled = (i.disabled === true || i.disabled === 'true');
    const state = running ? 'UP' : (disabled ? 'DISABLED' : 'DOWN');
    const rxErr = i['rx-error'] ?? 0;
    const txErr = i['tx-error'] ?? 0;
    const rxDrop = i['rx-drop'] ?? 0;
    const txDrop = i['tx-drop'] ?? 0;
    const linkDowns = i['link-downs'] ?? 0;
    return `${i.name} (${i.type || '?'}): ${state}, RX errors=${rxErr} drops=${rxDrop}, TX errors=${txErr} drops=${txDrop}, link-downs=${linkDowns}`;
  });

const hardwareSummary =
`CPU load: ${cpuLoad}%
Memory used: ${memUsedPct}% (${freeMem} bytes free of ${totalMem})
Uptime: ${uptime}
Board: ${boardName}

Health sensors:
${healthLines.length ? healthLines.join('\n') : '(no health sensors reported by this model)'}

Interfaces:
${ifaceSummaries.length ? ifaceSummaries.join('\n') : '(no interfaces found)'}`;

return [{
  json: {
    hardwareSummary,
    cpuLoad,
    memUsedPct,
    dateLabel: $('Compute Date Range').first().json.dateLabel
  }
}];

